nav{display:grid;gap:5px;padding-top:18px}button{font:inherit;transition:transform .08s ease,box-shadow .12s ease,background-color .12s ease,border-color .12s ease}.nav{border:0;background:transparent;color:#dce7f0;text-align:left;padding:12px;border-radius:9px;cursor:pointer;font-size:13px;font-weight:650}.nav:hover,.nav.active{background:#ffffff12;color:white}.nav.active{box-shadow:inset 3px 0 var(--gold)}.nav:active{transform:translateY(1px);background:#ffffff1c}.nav.clicked{box-shadow:inset 0 0 0 1px #ffffff22}.logout{margin-top:auto}
button:not(:disabled):active{transform:translateY(1px)}button.clicked:not(:disabled){box-shadow:0 0 0 2px rgba(15,49,78,.14),0 2px 5px rgba(15,49,78,.12)}.quick button:active{transform:translateY(2px);box-shadow:0 2px 5px rgba(15,49,78,.12)}.quick button.clicked{border-color:#7f9db5;background:#f7fafc}button:focus-visible{outline:3px solid rgba(15,49,78,.2);outline-offset:2px}
