  .main { min-width: 0; }
  .topbar {
    min-height: 68px;
    height: auto;
    padding: 11px 26px;
    background: rgba(255,255,255,.97);
    border-bottom-color: var(--ui-border);
    box-shadow: 0 2px 8px rgba(15,35,55,.025);
    backdrop-filter: blur(8px);
  }
  .title { color: #17344d; font-size: 18px; letter-spacing: -.2px; }
  .sub { color: var(--ui-muted); font-size: 11.5px; }
  .content { padding: 25px 26px 34px; }
  .content > * { min-width: 0; }
  .card, .placeholder, .hero, .login-card {
    border-color: var(--ui-border);
    box-shadow: var(--ui-shadow);
  }
  .card { border-radius: var(--ui-radius); }
  .section { color: #203d55; letter-spacing: -.1px; }
