  input:not([type="checkbox"]):not([type="radio"]),
  select, textarea {
    border-color: #d8e1ea;
    border-radius: 7px;
    color: var(--ui-text);
    transition: border-color .15s ease, box-shadow .15s ease, background-color .15s ease;
  }
  input:not([type="checkbox"]):not([type="radio"]):focus,
