@media screen {
  .dashboard-v3{--dash-ink:#142b43;--dash-blue:#245b86;--dash-gold:#d8b45a;}
  .dashboard-v3 .dash-welcome{min-height:230px;padding:34px 38px;border:1px solid #183d5c;border-radius:22px;background:radial-gradient(circle at 82% 18%,rgba(79,151,190,.34),transparent 27%),radial-gradient(circle at 100% 100%,rgba(216,180,90,.18),transparent 30%),linear-gradient(118deg,#10263d 0%,#173f60 57%,#245b79 100%);box-shadow:0 18px 38px rgba(17,48,75,.16);}
  .dashboard-v3 .dash-welcome:after{width:360px;height:360px;right:65px;top:-195px;border-color:rgba(255,255,255,.17);box-shadow:0 0 0 28px rgba(255,255,255,.035),0 0 0 58px rgba(255,255,255,.025),0 0 0 90px rgba(255,255,255,.018)}
  .dashboard-v3 .dash-eyebrow{color:#b9d3e5;letter-spacing:1.8px}.dashboard-v3 .dash-live-dot{background:#8bd4b1;box-shadow:0 0 0 5px rgba(139,212,177,.12)}
  .dashboard-v3 .dash-welcome h1{color:#fff;font-size:clamp(29px,3.1vw,39px);letter-spacing:-1.15px;margin-top:17px}.dashboard-v3 .dash-welcome p{color:#d1e0eb;font-size:13px;max-width:590px}
  .dashboard-v3 .dash-primary-action{background:linear-gradient(135deg,#e4c779,#cda94d);border-color:#e4c779;color:#172f45;box-shadow:0 7px 18px rgba(5,22,37,.2)}.dashboard-v3 .dash-primary-action:hover{background:#f0d58e;box-shadow:0 10px 22px rgba(5,22,37,.25)}
  .dashboard-v3 .dash-secondary-action{background:rgba(255,255,255,.10);border-color:rgba(255,255,255,.35);color:#fff;backdrop-filter:blur(8px)}.dashboard-v3 .dash-secondary-action:hover{background:rgba(255,255,255,.18);border-color:rgba(255,255,255,.55)}
  .dashboard-v3 .dash-welcome-mark{width:154px;height:154px;margin-right:22px}.dashboard-v3 .dash-mark-ring{border-color:rgba(255,255,255,.38);box-shadow:0 0 0 12px rgba(255,255,255,.07),0 0 0 25px rgba(255,255,255,.045)}.dashboard-v3 .dash-welcome-mark img{width:91px;height:91px;background:#fff;border-radius:18px;padding:7px;box-shadow:0 12px 28px rgba(0,0,0,.22)}.dashboard-v3 .dash-mark-label{background:#f5f8fb;border-color:rgba(255,255,255,.5);color:#173e5d}
  .dashboard-v3 .dash-section-heading{margin-bottom:16px}.dashboard-v3 .dash-section-heading h2{font-size:20px;color:#18354e}.dashboard-v3 .dash-kicker{color:#66839a}.dashboard-v3 .dash-stat-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:32px}
  .dashboard-v3 .dash-stat-card{position:relative;overflow:hidden;min-height:146px;padding:19px 19px 16px;border-radius:17px;border-color:#e0e8ef;box-shadow:0 7px 20px rgba(18,48,73,.045);background:linear-gradient(150deg,#fff 0%,#f8fbfd 100%)}
  .dashboard-v3 .dash-stat-card:before{content:"";position:absolute;inset:0 auto 0 0;width:4px;background:linear-gradient(180deg,#4d91b7,#d8b45a);opacity:.9}.dashboard-v3 .dash-stat-card:after{content:"";position:absolute;width:105px;height:105px;right:-48px;bottom:-57px;border:1px solid rgba(47,105,145,.10);border-radius:50%;box-shadow:0 0 0 13px rgba(47,105,145,.025),0 0 0 27px rgba(47,105,145,.018);pointer-events:none}
  .dashboard-v3 .dash-stat-card:hover{transform:translateY(-4px);border-color:#b9d0df;box-shadow:0 14px 27px rgba(18,48,73,.09)}.dashboard-v3 .dash-stat-icon{background:linear-gradient(145deg,#eaf3f8,#dceaf2);color:#245b80;border-radius:12px}.dashboard-v3 .dash-stat-value{font-size:37px;color:#163c5b;letter-spacing:-1.4px}.dashboard-v3 .dash-stat-label{color:#526e83}.dashboard-v3 .dash-stat-foot{color:#8093a2}
  .dashboard-v3 .dash-stat-total{background:linear-gradient(145deg,#f0faf7 0%,#fff 74%)}.dashboard-v3 .dash-stat-total:before{background:linear-gradient(180deg,#38a17d,#8bd4b1)}
  .dashboard-v3 .dash-quick-card,.dashboard-v3 .dash-search-panel,.dashboard-v3 .dash-panel{border-radius:17px;border-color:#e0e8ef;box-shadow:0 7px 20px rgba(18,48,73,.045)}.dashboard-v3 .dash-quick-card{padding:19px 20px;background:linear-gradient(145deg,#fff,#f8fbfd)}.dashboard-v3 .dash-quick-card:hover{transform:translateY(-3px);box-shadow:0 13px 25px rgba(18,48,73,.085);border-color:#b8cfdf}.dashboard-v3 .dash-quick-icon{border-radius:13px;background:linear-gradient(145deg,#e8f2f8,#dceaf2);color:#245b80}.dashboard-v3 .dash-quick-copy strong{font-size:12px;color:#183c58}
  .dashboard-v3 .dash-search-panel{padding:23px 25px;background:linear-gradient(125deg,#fff 0%,#f4f8fb 100%)}.dashboard-v3 .dash-search-symbol{background:#e7f0f6;color:#245b80;border-radius:12px}.dashboard-v3 .dash-search-control input{height:46px;border-radius:12px;background:#fff}.dashboard-v3 .dash-search-control .search-btn{height:46px;border-radius:12px;background:#173f60}.dashboard-v3 .dash-panel{padding:23px 24px}.dashboard-v3 .dash-panel-heading h3{font-size:14px}.dashboard-v3 .dash-panel-icon{border-radius:11px;background:#eaf2f7;color:#245b80}
  .dashboard-v3 .dash-dist-row .bar-track{height:9px;background:#eaf0f4}.dashboard-v3 .dash-dist-row .grade-11-fill{background:linear-gradient(90deg,#245b86,#58a0c1)}.dashboard-v3 .dash-dist-row .grade-12-fill{background:linear-gradient(90deg,#c79e43,#e8ce83)}
  .dashboard-v3 .dash-activity-table th{background:#f0f5f8;color:#617d91}.dashboard-v3 .dash-activity-table tbody tr:hover td{background:#f8fbfd}
}
@media screen and (max-width:1100px){.dashboard-v3 .dash-stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media screen and (max-width:650px){.dashboard-v3 .dash-welcome{padding:25px 21px}.dashboard-v3 .dash-stat-grid{grid-template-columns:1fr}.dashboard-v3 .dash-welcome h1{font-size:27px}}
@media screen and (prefers-reduced-motion:reduce){.dashboard-v3 .dash-stat-card,.dashboard-v3 .dash-quick-card{transition:none}}


                                                                          
.dashboard-v3 .dash-primary-action{background:#173c5b !important;border:1px solid #173c5b !important;color:#fff !important;box-shadow:0 4px 10px rgba(23,60,91,.12) !important}
.dashboard-v3 .dash-primary-action:hover{background:#245579 !important;transform:translateY(-1px);box-shadow:0 7px 15px rgba(23,60,91,.16) !important}
.dashboard-v3 .dash-secondary-action{border:1px solid #cbd9e4 !important;background:rgba(255,255,255,.75) !important;color:#244a68 !important;backdrop-filter:none !important}
.dashboard-v3 .dash-secondary-action:hover{background:#fff !important;border-color:#9fb7c9 !important}


                                                                          
.ces-credit-footer{position:relative;display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;padding:9px 16px 12px;margin:0 24px;color:#8290a3;font-size:10px;line-height:1.4;text-align:center;border-top:1px solid rgba(120,138,160,.16);box-sizing:border-box}
.ces-team-disclosure{position:static;display:inline-block;color:#526b86;font-size:10px}
.ces-team-disclosure summary{cursor:pointer;list-style:none;font-weight:700;text-decoration:underline;text-underline-offset:2px}
.ces-team-disclosure summary::-webkit-details-marker{display:none}
.ces-team-panel{position:static;z-index:auto;width:min(100%,560px);box-sizing:border-box;margin:10px auto 0;padding:11px 14px;background:#fff;border:1px solid #dce4ee;border-radius:10px;box-shadow:0 5px 16px rgba(24,45,72,.08);text-align:left;color:#26384c}
.ces-team-lead{display:flex;flex-direction:column;gap:2px;margin:0 0 9px;padding-bottom:8px;border-bottom:1px solid #e8edf3;font-size:11px}
.ces-team-lead span{color:#718198;font-size:10px}
.ces-team-panel ul{display:grid;grid-template-columns:1fr 1fr;gap:6px 12px;margin:0;padding:0;list-style:none;font-size:10px}
@media(max-width:600px){.ces-credit-footer{margin:0 12px;padding:8px 8px 11px;gap:5px}.ces-team-panel{width:100%;margin-top:8px}.ces-team-panel ul{grid-template-columns:1fr 1fr;gap:6px 8px}}


                                                                                 
.app > .main{display:flex;flex-direction:column;min-height:100vh;min-width:0}
.app > .main > .content{flex:1 0 auto;width:100%;box-sizing:border-box}
.app > .main > .ces-credit-footer{display:flex;position:relative;flex:0 0 auto;width:100%;max-width:none;margin:0;padding:12px 24px 16px;box-sizing:border-box;justify-content:center;align-items:center;text-align:center}
.ces-team-disclosure[open] .ces-team-panel{position:static;display:block}
@media(max-width:700px){.app > .main{min-height:100dvh}.app > .main > .ces-credit-footer{padding:10px 14px 14px;gap:6px}}


                                                                     
.login-team-disclosure{position:relative;margin:8px auto 0;text-align:center;color:#526b86;font-size:9px;line-height:1.4}
.login-team-disclosure summary{display:inline-block;cursor:pointer;list-style:none;font-weight:700;text-decoration:underline;text-underline-offset:2px}
.login-team-disclosure summary::-webkit-details-marker{display:none}
.login-team-panel{width:min(100%,420px);box-sizing:border-box;margin:8px auto 0;padding:10px 12px;background:#fff;border:1px solid #dce4ee;border-radius:9px;box-shadow:0 5px 16px rgba(24,45,72,.08);text-align:left;color:#26384c}
.login-team-lead{display:flex;flex-direction:column;gap:2px;margin:0 0 8px;padding-bottom:7px;border-bottom:1px solid #e8edf3;font-size:10px}
.login-team-lead span{color:#718198;font-size:9px}
.login-team-panel ul{display:grid;grid-template-columns:1fr 1fr;gap:5px 10px;margin:0;padding:0;list-style:none;font-size:9px}
@media(max-width:760px){.login-team-panel{width:100%;max-width:360px}.login-team-panel ul{gap:5px 8px}}

                                                                                           
.ces-team-lead .ces-class-credit{display:block;color:#718198;font-size:10px;font-weight:400;letter-spacing:normal;line-height:1.4;text-align:left;margin:0}


                                                                                    
.ces-team-panel .ces-team-lead > .ces-class-credit {
  display: block !important;
  visibility: visible !important;
  color: #718198 !important;
  font-size: 10px !important;
  font-weight: 400 !important;
  line-height: 1.4 !important;
  letter-spacing: normal !important;
  text-align: left !important;
  margin: 0 !important;
}


                                  
                                                                         
                                                                          
